<?php
namespace App\Http\Controllers\API;
use App\Enums\ExpenseStatus; use App\Http\Controllers\Controller; use App\Http\Resources\ExpenseResource; use App\Models\Expense; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule;
class ExpenseController extends Controller { public function index(Request $r) { $items=Expense::with('staff')->where('owner_id',$r->user()->id)->latest()->paginate(20); return ExpenseResource::collection($items)->response(); } public function store(Request $r): JsonResponse { $d=$r->validate(['staff_id'=>['required','exists:staff,id'],'title'=>['required','string','max:255'],'category'=>['required','string','max:100'],'amount'=>['required','numeric','min:0.01'],'expense_date'=>['required','date'],'reason'=>['nullable','string','max:1000']]);$r->user()->staff()->findOrFail($d['staff_id']);$item=Expense::create([...$d,'owner_id'=>$r->user()->id,'status'=>ExpenseStatus::Pending->value]);return response()->json(new ExpenseResource($item->load('staff')),201); } public function updateStatus(Request $r, Expense $expense): JsonResponse { abort_unless($expense->owner_id===$r->user()->id,403);$d=$r->validate(['status'=>['required',Rule::enum(ExpenseStatus::class)]]);$expense->update($d);return response()->json(new ExpenseResource($expense->load('staff'))); } }
